import { createStore } from 'vuex';

export default createStore({
  state: {
    user: null, // 存储用户信息
    token: null, // 存储 Token
  },
  mutations: {
    setUser(state, user) {
      state.user = user;
    },
    setToken(state, token) {
      state.token = token;
    },
    clearUser(state) {
      state.user = null;
    },
    clearToken(state) {
      state.token = null;
    },
  },
  actions: {
    login({ commit }, { user, token }) {
      commit('setUser', user);
      commit('setToken', token);
    },
    logout({ commit }) {
      commit('clearUser');
      commit('clearToken');
    },
  },
  getters: {
    user: (state) => state.user,
    token: (state) => state.token,
  },
});
